import pty, os, tty, termios
m, s = pty.openpty()
print(os.isatty(m), os.isatty(s))
os.write(m, b"hi\n")
print(os.read(s, 10))
os.write(s, b"yo\n")
print(os.read(m, 10))
print(pty.STDIN_FILENO, pty.STDOUT_FILENO, pty.STDERR_FILENO, pty.CHILD)
print(sorted(pty.__all__))
tty.setraw(s)
os.write(m, b"abc")
print(os.read(s, 3))
os.close(m); os.close(s)
